//! The ground as physics sees it (#1949): blocks generated by the same GPU pass that draws them,
//! read back and meshed on the CPU with the GPU mesher's placement, so a body rests on what is drawn.

#[cfg(feature = "physics")]
mod gpu;
mod mesh;
#[cfg(feature = "physics")]
mod patch;
#[cfg(feature = "physics")]
#[cfg(feature = "physics")]
mod sync;
#[cfg(feature = "physics")]
mod view;

#[cfg(feature = "physics")]
use mesh::mesh_block;
#[cfg(feature = "physics")]
pub use sync::{GroundColliders, GroundInvoker, GroundWire, release_ground, sync_ground};
#[cfg(feature = "physics")]
pub use view::{BlockState, BlockView, GroundView};

/// Registers the invoker and inserts the ground's state.
#[cfg(feature = "physics")]
pub(crate) fn register(resources: &mut kooch_core::resource::Resources) {
    use kooch_ecs::component::ComponentRegistry;
    if let Some(registry) = resources.get_mut::<ComponentRegistry>() {
        registry.register_cpu_reflected::<GroundInvoker>();
    }
    resources.insert(GroundColliders::default());
}
